            C

    // C program to reverse a number
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void reverse(char* begin, char* end) {
    char temp;
    while (begin < end) {
        temp = *begin;
        *begin++ = *end;
        *end-- = temp;
    }
}

void reverseWords(char* s) {
    char* word_begin = s;
    char* temp = s;

    // Reversing individual words as explained in the first step
    while (*temp) {
        temp++;
        if (*temp == '\0') {
            reverse(word_begin, temp - 1);
        }
        else if (*temp == ' ') {
            reverse(word_begin, temp - 1);
            word_begin = temp + 1;
        }
    }
    reverse(s, temp - 1);
}

int reverseDigits(int n) {
    char strin[100];
    sprintf(strin, "%d", n);

    // reversing the string
    reverseWords(strin);

    // converting string to integer
    n = atoi(strin);

    return n;
}

int main() {
    int n = 123456;
    printf("%d\n",reverseDigits(n));
    return 0;
}


