function reverseDigits(n)
{
    // converting number to string
    let s = n.toString().split("").reverse().join("");

    // removing leading 0s
    while (s[0] === '0') {
        s = s.slice(1);
    }

    // converting string to integer
    n = parseInt(s);

    // returning integer
    return n;
}

